def hook(ctx, nb):
    p = ctx.get('predicates') or {}
    s = ctx.get('state') or {}
    stage = nb.get('stage') or 'start'
    if p.get('unknown_column_error') or p.get('syntax_error') or s.get('last_error_kind') in ('unknown_col', 'syntax'):
        stage = 'need_schema_probe'
        nb['fixing_unknown_column'] = bool(p.get('unknown_column_error'))
    elif p.get('last_result_empty') and not p.get('mutation_task'):
        stage = 'fixing_empty_result'
    elif p.get('repeated_sql') or (s.get('loop_streak') or 0) >= 2:
        stage = 'repeated_query_loop'
    elif p.get('text_only_loop') or (s.get('text_only_streak') or 0) >= 2:
        stage = 'text_numeric_check'
    elif p.get('mutation_task') and p.get('mutation_not_attempted'):
        stage = 'mutation_needs_execution'
    elif p.get('mutation_task') and s.get('mutation_attempted'):
        stage = 'ready_to_commit_candidate'
    if p.get('candidate_answer_available') and not s.get('candidate_implausible'):
        nb['candidate_answer_available'] = True
    if p.get('remaining_rounds_low'):
        nb['remaining_rounds_low'] = True
    nb['stage'] = stage
    return None

def hook(ctx, nb):
    stage = nb.get('stage')
    msg = ''
    if stage == 'need_schema_probe':
        msg = 'Schema recovery: use SHOW TABLES, then DESCRIBE the exact table name. Backtick every table or column identifier that has spaces, punctuation, or is a reserved word; do not invent underscore names.'
    elif stage == 'fixing_empty_result':
        msg = 'Empty SELECT recovery: inspect a few sample rows or distinct values for the filtered columns, then relax one predicate or adjust quoting/casting. Text numerics may need CAST for numeric comparison or ordering.'
    elif stage == 'repeated_query_loop':
        msg = 'Repeated SQL loop: change the debugging step instead of rerunning the same query. Probe schema, sample values, or loosen filters before trying again.'
    elif stage == 'text_numeric_check':
        msg = 'Text numeric check: if ranking, sorting, or aggregating over TEXT columns, cast cleaned values to SIGNED or DECIMAL for numeric operations, but keep original text for final display when needed.'
    elif stage == 'mutation_needs_execution':
        msg = 'Mutation task: execute the INSERT, UPDATE, or DELETE before committing. In MySQL, backtick non-simple identifiers and preserve exact requested literals, including spaces, punctuation, commas, percent signs, and newlines.'
    elif stage == 'ready_to_commit_candidate':
        msg = 'Mutation verification: an empty result from UPDATE, INSERT, or DELETE can still mean success. If rounds allow, verify the affected row/state, then commit a brief completion answer.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

def hook(ctx, nb):
    a = ctx.get('action') or {}
    p = ctx.get('predicates') or {}
    if a.get('tool') != 'commit_final_answer':
        return None
    if p.get('commit_before_sql') or p.get('no_sql_yet'):
        return {'kind': 'block_and_prompt', 'message': 'Run at least one SQL query to inspect or modify the database before committing a final answer.'}
    if p.get('commit_empty_answer') and not (p.get('mutation_task') and (nb.get('stage') == 'ready_to_commit_candidate' or (ctx.get('state') or {}).get('mutation_attempted'))):
        return {'kind': 'block_and_prompt', 'message': 'Do not commit an empty answer for a SELECT-style task. Use SQL evidence to provide the requested raw values or row count.'}
    if p.get('mutation_task') and p.get('mutation_not_attempted'):
        return {'kind': 'block_and_prompt', 'message': 'This is a data-changing task. Execute the INSERT, UPDATE, or DELETE first, preserving exact requested literals and using MySQL backticks for non-simple identifiers.'}
    return None
